-- Run in Supabase SQL Editor after 001_personal_auth.sql.
begin;
create table if not exists public.recommendation_catalogues (
  version text primary key, published_at timestamptz not null, observed_at date,
  status text not null check (status in ('illustrative')), payload jsonb not null,
  is_current boolean not null default false
);
create unique index if not exists one_current_recommendation_catalogue on public.recommendation_catalogues(is_current) where is_current;
alter table public.recommendation_catalogues enable row level security;
drop policy if exists "Read practice catalogue" on public.recommendation_catalogues;
create policy "Read practice catalogue" on public.recommendation_catalogues for select to authenticated using (true);
grant select on public.recommendation_catalogues to authenticated;

create table if not exists public.recommendation_runs (
  id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade,
  request_hash text not null, kind text not null check (kind in ('explain','plan')),
  status text not null check (status in ('generating','complete','failed')),
  lease uuid not null default gen_random_uuid(), started_at timestamptz not null default now(),
  result jsonb, error_code text, profile_snapshot jsonb not null, preferences_snapshot jsonb not null,
  unique(user_id, request_hash)
);
alter table public.recommendation_runs enable row level security;
drop policy if exists "Read own recommendation runs" on public.recommendation_runs;
create policy "Read own recommendation runs" on public.recommendation_runs for select to authenticated using ((select auth.uid())=user_id);
grant select on public.recommendation_runs to authenticated;

create table if not exists public.ai_request_attempts (
  id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade,
  started_at timestamptz not null default now()
);
create index if not exists ai_attempts_time on public.ai_request_attempts(started_at);
alter table public.ai_request_attempts enable row level security;

create table if not exists public.active_learning_plans (
  user_id uuid primary key references auth.users(id) on delete cascade,
  run_id uuid not null references public.recommendation_runs(id), activated_at timestamptz not null default now()
);
alter table public.active_learning_plans enable row level security;
drop policy if exists "Read own active plan" on public.active_learning_plans;
create policy "Read own active plan" on public.active_learning_plans for select to authenticated using ((select auth.uid())=user_id);
grant select on public.active_learning_plans to authenticated;

create table if not exists public.learning_completions (
  user_id uuid not null references auth.users(id) on delete cascade,
  course_id text not null, course_version text not null, activity_id text not null,
  completed boolean not null default true, updated_at timestamptz not null default now(),
  primary key(user_id,course_id,course_version,activity_id)
);
alter table public.learning_completions enable row level security;
drop policy if exists "Own learning completions" on public.learning_completions;
create policy "Own learning completions" on public.learning_completions for all to authenticated
  using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
grant select, insert, update, delete on public.learning_completions to authenticated;
revoke all on public.recommendation_catalogues, public.recommendation_runs, public.ai_request_attempts, public.active_learning_plans, public.learning_completions from anon;
grant all on public.recommendation_catalogues, public.recommendation_runs, public.ai_request_attempts, public.active_learning_plans, public.learning_completions to service_role;

-- Only the Edge Function can reserve capacity. Atomic, durable limits survive
-- multiple function instances. Failed provider attempts count toward the limits.
create or replace function public.reserve_recommendation(p_user_id uuid, p_request_hash text, p_kind text, p_profile jsonb, p_preferences jsonb)
returns jsonb language plpgsql security invoker set search_path='' as $$
declare existing public.recommendation_runs; current_profile jsonb; current_preferences jsonb;
begin
  perform pg_advisory_xact_lock(81273108);
  select profile, journey->'plan' into current_profile, current_preferences
    from public.personal_profiles where user_id=p_user_id for update;
  -- Skills live in their own table; include them in the immutable input snapshot.
  current_profile := current_profile || jsonb_build_object('skills', (select ratings from public.skill_assessments where user_id=p_user_id));
  if current_profile is distinct from p_profile or (p_kind='plan' and current_preferences is distinct from p_preferences)
    then raise exception 'PROFILE_CHANGED: Save and confirm your current profile/preferences before generating'; end if;
  select * into existing from public.recommendation_runs where user_id=p_user_id and request_hash=p_request_hash;
  if existing.status='complete' then return jsonb_build_object('cached',true,'run',to_jsonb(existing)); end if;
  if exists(select 1 from public.recommendation_runs where user_id=p_user_id and status='generating' and started_at>now()-interval '90 seconds')
    then raise exception 'IN_PROGRESS: A request is already running. Please wait'; end if;
  if (select count(*) from public.ai_request_attempts where started_at>now()-interval '1 minute')>=4
    or (select count(*) from public.ai_request_attempts where started_at>=date_trunc('day',now() at time zone 'UTC') at time zone 'UTC')>=18
    or (select count(*) from public.ai_request_attempts where user_id=p_user_id and started_at>now()-interval '1 minute')>=2
    or (select count(*) from public.ai_request_attempts where user_id=p_user_id and started_at>=date_trunc('day',now() at time zone 'UTC') at time zone 'UTC')>=8
    then raise exception 'RATE_LIMIT: Practice AI allowance reached. Try later; saved results remain available'; end if;
  insert into public.ai_request_attempts(user_id) values(p_user_id);
  insert into public.recommendation_runs(user_id,request_hash,kind,status,profile_snapshot,preferences_snapshot)
    values(p_user_id,p_request_hash,p_kind,'generating',p_profile,p_preferences)
    on conflict(user_id,request_hash) do update set status='generating',lease=gen_random_uuid(),started_at=now(),error_code=null
    returning * into existing;
  return jsonb_build_object('cached',false,'run',to_jsonb(existing));
end;
$$;

create or replace function public.finish_recommendation(p_run_id uuid, p_lease uuid, p_result jsonb)
returns jsonb language plpgsql security invoker set search_path='' as $$
declare r public.recommendation_runs; profile_now jsonb; pref_now jsonb;
begin
  select * into r from public.recommendation_runs where id=p_run_id and lease=p_lease and status='generating' for update;
  if not found then raise exception 'STALE_REQUEST: Please generate again'; end if;
  select profile,journey->'plan' into profile_now,pref_now from public.personal_profiles where user_id=r.user_id for update;
  profile_now := profile_now || jsonb_build_object('skills',(select ratings from public.skill_assessments where user_id=r.user_id));
  if profile_now is distinct from r.profile_snapshot or (r.kind='plan' and pref_now is distinct from r.preferences_snapshot)
    then raise exception 'PROFILE_CHANGED: Your inputs changed during generation. Confirm and try again'; end if;
  update public.recommendation_runs set status='complete',result=p_result where id=p_run_id returning * into r;
  return to_jsonb(r);
end;
$$;

create or replace function public.activate_learning_plan(p_run_id uuid)
returns void language plpgsql security definer set search_path='' as $$
declare r public.recommendation_runs; current_profile jsonb; current_preferences jsonb;
begin
  if auth.uid() is null then raise exception 'Sign in first' using errcode='42501'; end if;
  select * into r from public.recommendation_runs where id=p_run_id and user_id=auth.uid() and kind='plan' and status='complete';
  if not found or jsonb_array_length(r.result#>'{plan,missing}')<>0 or jsonb_array_length(r.result#>'{plan,modules}')=0
    then raise exception 'Choose a complete, saved plan belonging to your account'; end if;
  select profile,journey->'plan' into current_profile,current_preferences from public.personal_profiles where user_id=auth.uid() for update;
  current_profile := current_profile || jsonb_build_object('skills',(select ratings from public.skill_assessments where user_id=auth.uid()));
  if current_profile is distinct from r.profile_snapshot or (current_preferences-'saved') is distinct from (r.preferences_snapshot-'saved')
    then raise exception 'Inputs changed. Generate a revised plan before activating it'; end if;
  insert into public.active_learning_plans(user_id,run_id) values(auth.uid(),p_run_id)
    on conflict(user_id) do update set run_id=excluded.run_id,activated_at=now();
end;
$$;
revoke all on function public.reserve_recommendation(uuid,text,text,jsonb,jsonb), public.finish_recommendation(uuid,uuid,jsonb) from public,anon,authenticated;
grant execute on function public.reserve_recommendation(uuid,text,text,jsonb,jsonb), public.finish_recommendation(uuid,uuid,jsonb) to service_role;
revoke all on function public.activate_learning_plan(uuid) from public,anon;
grant execute on function public.activate_learning_plan(uuid) to authenticated;
commit;
